const pptxgen = require("pptxgenjs");

const slideConfig = { type: "cover", index: 1, title: "Global CO₂ Emissions" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Large geometric accent shape
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 1.2, fill: { color: theme.secondary, transparency: 30 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.5, y: 0, w: 3.5, h: 5.625, fill: { color: theme.secondary, transparency: 20 }
  });

  // Main title
  slide.addText("Global CO₂ Emissions", {
    x: 0.6, y: 1.4, w: 8.5, h: 1.3,
    fontSize: 42, fontFace: "Georgia", color: "FFFFFF", bold: true, align: "left", fit: "shrink"
  });

  // Subtitle line 1
  slide.addText("Who Emits, How Much, and What's Changing", {
    x: 0.6, y: 2.7, w: 8, h: 0.7,
    fontSize: 24, fontFace: "Calibri", color: theme.accent, bold: false, align: "left"
  });

  // Scope line
  slide.addText("Fossil Fuels & Industry  |  1750–2024", {
    x: 0.6, y: 3.5, w: 6, h: 0.5,
    fontSize: 16, fontFace: "Calibri", color: "CCCCCC", bold: false, align: "left"
  });

  // Accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 4.2, w: 2.5, h: 0.04, fill: { color: theme.accent }
  });

  // Source attribution
  slide.addText("Data: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.6, y: 4.4, w: 6, h: 0.4,
    fontSize: 11, fontFace: "Calibri", color: "AAAAAA", bold: false, align: "left"
  });

  // Authors
  slide.addText("Hannah Ritchie & Max Roser", {
    x: 0.6, y: 4.75, w: 4, h: 0.35,
    fontSize: 10, fontFace: "Calibri", color: "888888", bold: false, align: "left"
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

