const slideConfig = { type: "content", index: 2, title: "Global CO₂ Emissions Growth" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText("Global CO₂ Emissions Grew from 6 Bt in 1950 to Over 35 Bt Today", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 22, fontFace: "Georgia", color: theme.primary, bold: true, align: "left",
    margin: 0, fit: "shrink"
  });

  // Area chart showing emission trajectory
  const labels = ["1750","1800","1850","1900","1920","1950","1960","1970","1980","1990","2000","2010","2020","2024"];
  const values = [0.01, 0.03, 0.2, 2, 3.5, 6, 9, 14, 18, 20, 24, 30, 34, 35.5];

  slide.addChart(pres.charts.LINE, [{
    name: "Global CO₂ (Bt/yr)",
    labels: labels,
    values: values
  }], {
    x: 0.5, y: 1.2, w: 6.2, h: 3.8,
    showTitle: false,
    lineSize: 3,
    lineSmooth: true,
    chartColors: [theme.secondary],
    chartArea: { fill: { color: "FAFAFA" } },
    catAxisLabelColor: "666666",
    valAxisLabelColor: "666666",
    catAxisLabelFontSize: 9,
    valAxisLabelFontSize: 9,
    valGridLine: { color: "E8E8E8", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    fill: { color: theme.secondary }
  });

  // Annotation callouts on the right
  const annotations = [
    { label: "Pre-1900", value: "Negligible emissions", color: theme.secondary },
    { label: "1950", value: "~6 Bt/yr", color: theme.accent },
    { label: "1990", value: "~20 Bt — nearly 4× 1950", color: theme.light },
    { label: "2024", value: ">35 Bt — no peak yet", color: "e76f51" }
  ];

  let ay = 1.3;
  annotations.forEach((a) => {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 7.1, y: ay, w: 0.06, h: 0.7, fill: { color: a.color }
    });
    slide.addText(a.label, {
      x: 7.3, y: ay, w: 2.3, h: 0.3,
      fontSize: 12, fontFace: "Georgia", color: theme.primary, bold: true, align: "left", margin: 0
    });
    slide.addText(a.value, {
      x: 7.3, y: ay + 0.3, w: 2.3, h: 0.35,
      fontSize: 11, fontFace: "Calibri", color: "555555", bold: false, align: "left", margin: 0
    });
    ay += 0.9;
  });

  // Source
  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.5, y: 5.15, w: 5, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: "999999", bold: false, align: "left", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("2", { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  return slide;
}

module.exports = { createSlide, slideConfig };

