const pptxgen = require("pptxgenjs");

const slideConfig = { type: "content", index: 3, title: "Regional Share Shift" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  slide.addText("Europe and the US Fell from 90% of Emissions in 1900 to Under One-Third Today", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 20, fontFace: "Georgia", color: theme.primary, bold: true, align: "left",
    margin: 0, fit: "shrink"
  });

  // Stacked area chart placeholder — use grouped bar to show share shift over time
  const labels = ["1900", "1950", "2024"];

  slide.addChart(pres.charts.BAR, [
    { name: "Europe & US", labels: labels, values: [90, 85, 32] },
    { name: "China", labels: labels, values: [0, 2, 31] },
    { name: "India", labels: labels, values: [0, 1, 8] },
    { name: "Rest of World", labels: labels, values: [10, 12, 29] }
  ], {
    x: 0.5, y: 1.2, w: 5.8, h: 3.8,
    showTitle: false,
    barDir: "col",
    barGrouping: "stacked",
    chartColors: [theme.primary, "e76f51", theme.accent, theme.secondary],
    chartArea: { fill: { color: "FAFAFA" } },
    catAxisLabelColor: "666666",
    valAxisLabelColor: "666666",
    catAxisLabelFontSize: 10,
    valAxisLabelFontSize: 9,
    valGridLine: { color: "E8E8E8", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: true,
    legendPos: "b",
    legendFontSize: 9,
    valAxisMaxVal: 100,
    showValue: false
  });

  // Key insight cards on right
  const insights = [
    { stat: ">90%", text: "Europe & US share\nin 1900" },
    { stat: "<⅓", text: "Europe & US share\ntoday" },
    { stat: "~50%", text: "Asia's share today,\nled by China" }
  ];

  let iy = 1.3;
  insights.forEach((item, idx) => {
    const bgColors = [theme.primary, "e76f51", theme.secondary];
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.8, y: iy, w: 2.8, h: 1.05, fill: { color: bgColors[idx] }, rectRadius: 0
    });
    slide.addText(item.stat, {
      x: 6.9, y: iy + 0.05, w: 2.6, h: 0.5,
      fontSize: 26, fontFace: "Georgia", color: "FFFFFF", bold: true, align: "center", margin: 0
    });
    slide.addText(item.text, {
      x: 6.9, y: iy + 0.55, w: 2.6, h: 0.4,
      fontSize: 10, fontFace: "Calibri", color: "FFFFFF", bold: false, align: "center", margin: 0
    });
    iy += 1.2;
  });

  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.5, y: 5.15, w: 5, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: "999999", bold: false, align: "left", margin: 0
  });

  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("3", { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  return slide;
}

module.exports = { createSlide, slideConfig };

