const pptxgen = require("pptxgenjs");

const slideConfig = { type: "content", index: 4, title: "China Dominates Share" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  slide.addText("China Now Emits More Than One-Quarter of Global CO₂", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 22, fontFace: "Georgia", color: theme.primary, bold: true, align: "left", margin: 0
  });

  // Horizontal bar chart for country shares
  const countries = ["Int'l Aviation & Shipping", "South America", "Africa", "Russia", "EU-27", "India", "United States", "China"];
  const shares = [3, 3.5, 3.5, 5, 6, 8, 13, 31];

  slide.addChart(pres.charts.BAR, [{
    name: "Share of Global CO₂ (%)",
    labels: countries,
    values: shares
  }], {
    x: 0.5, y: 1.1, w: 6, h: 4,
    showTitle: false,
    barDir: "bar",
    chartColors: ["e76f51"],
    chartArea: { fill: { color: "FAFAFA" } },
    catAxisLabelColor: "444444",
    valAxisLabelColor: "666666",
    catAxisLabelFontSize: 10,
    valAxisLabelFontSize: 9,
    valGridLine: { color: "E8E8E8", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: "333333",
    dataLabelFontSize: 10,
    valAxisHidden: true
  });

  // Key callout on the right
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7, y: 1.3, w: 2.6, h: 2.2, fill: { color: theme.primary }
  });
  slide.addText("~31%", {
    x: 7.1, y: 1.4, w: 2.4, h: 0.9,
    fontSize: 44, fontFace: "Georgia", color: theme.accent, bold: true, align: "center", margin: 0
  });
  slide.addText("China's share of\nglobal CO₂ in 2024", {
    x: 7.1, y: 2.3, w: 2.4, h: 0.6,
    fontSize: 12, fontFace: "Calibri", color: "CCCCCC", bold: false, align: "center", margin: 0
  });

  // Trend badges
  const trends = [
    { country: "China", trend: "Rising, growth slowing", y: 3.8 },
    { country: "US", trend: "Declining", y: 4.15 },
    { country: "India", trend: "Rising", y: 4.5 }
  ];
  trends.forEach((t) => {
    slide.addText(t.country + ": " + t.trend, {
      x: 7.1, y: t.y, w: 2.5, h: 0.3,
      fontSize: 10, fontFace: "Calibri", color: "555555", bold: false, align: "left", margin: 0
    });
  });

  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data  |  Approx. 2024 shares", {
    x: 0.5, y: 5.15, w: 6, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: "999999", bold: false, align: "left", margin: 0
  });

  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("4", { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  return slide;
}

module.exports = { createSlide, slideConfig };

