const pptxgen = require("pptxgenjs");

const slideConfig = { type: "content", index: 7, title: "2024 Annual Change" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  slide.addText("2024: Many Western Nations Cut Emissions While Parts of Asia and Africa Grew", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 20, fontFace: "Georgia", color: theme.primary, bold: true, align: "left",
    margin: 0, fit: "shrink"
  });

  // Diverging bar chart — declining vs growing
  slide.addText("Emissions Declining", {
    x: 0.5, y: 1.15, w: 4.2, h: 0.35,
    fontSize: 13, fontFace: "Georgia", color: theme.secondary, bold: true, align: "left", margin: 0
  });

  const declining = [
    { name: "United States", val: -3 },
    { name: "EU-27", val: -4 },
    { name: "United Kingdom", val: -3 }
  ];

  declining.forEach((d, i) => {
    const by = 1.65 + i * 0.65;
    const barW = Math.abs(d.val) * 0.35;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: by, w: 4.2, h: 0.5, fill: { color: "F5F5F0" }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: by, w: barW, h: 0.5, fill: { color: theme.secondary }
    });
    slide.addText(d.name, {
      x: 0.6, y: by, w: 2.5, h: 0.5,
      fontSize: 11, fontFace: "Calibri", color: theme.primary, bold: false, align: "left", valign: "middle", margin: 0
    });
    slide.addText(d.val + "%", {
      x: 3.2, y: by, w: 1.2, h: 0.5,
      fontSize: 12, fontFace: "Calibri", color: theme.secondary, bold: true, align: "right", valign: "middle", margin: 0
    });
  });

  // Growing side
  slide.addText("Emissions Growing", {
    x: 5.3, y: 1.15, w: 4.2, h: 0.35,
    fontSize: 13, fontFace: "Georgia", color: "e76f51", bold: true, align: "left", margin: 0
  });

  const growing = [
    { name: "Russia", val: "+2" },
    { name: "Parts of SE Asia", val: "+3–5" },
    { name: "Central Asia", val: ">+10" },
    { name: "Several African nations", val: "+2–5" }
  ];

  growing.forEach((g, i) => {
    const by = 1.65 + i * 0.65;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.3, y: by, w: 4.2, h: 0.5, fill: { color: "FDF5F3" }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.3, y: by, w: 1.2, h: 0.5, fill: { color: "e76f51" }
    });
    slide.addText(g.name, {
      x: 5.4, y: by, w: 2.6, h: 0.5,
      fontSize: 11, fontFace: "Calibri", color: theme.primary, bold: false, align: "left", valign: "middle", margin: 0
    });
