const pptxgen = require("pptxgenjs");

const slideConfig = { type: "content", index: 8, title: "Energy Mix Matters" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  slide.addText("Energy Mix Explains Why France and the UK Emit Far Less Per Capita Than Germany or the US", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 19, fontFace: "Georgia", color: theme.primary, bold: true, align: "left",
    margin: 0, fit: "shrink"
  });

  // Comparative bar chart — per capita for wealthy nations
  const countries = ["United States", "Germany (est.)", "EU-27 avg.", "United Kingdom", "France (est.)"];
  const values = [14, 8, 6, 4, 4.5];

  slide.addChart(pres.charts.BAR, [{
    name: "Per Capita CO₂ (t/person, approx. 2024)",
    labels: countries,
    values: values
  }], {
    x: 0.5, y: 1.2, w: 5.2, h: 3.2,
    showTitle: false,
    barDir: "bar",
    chartColors: [theme.primary],
    chartArea: { fill: { color: "FAFAFA" } },
    catAxisLabelColor: "444444",
    valAxisLabelColor: "666666",
    catAxisLabelFontSize: 10,
    valAxisLabelFontSize: 9,
    valGridLine: { color: "E8E8E8", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: "333333",
    dataLabelFontSize: 10,
