const pptxgen = require("pptxgenjs");

const slideConfig = { type: "summary", index: 9, title: "Key Takeaways" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  slide.addText("Key Takeaways", {
    x: 0.6, y: 0.3, w: 8, h: 0.7,
    fontSize: 32, fontFace: "Georgia", color: "FFFFFF", bold: true, align: "left", margin: 0
  });

  slide.addText("Responsibility Is Shared but Unequal", {
    x: 0.6, y: 0.95, w: 8, h: 0.4,
    fontSize: 16, fontFace: "Calibri", color: theme.accent, bold: false, align: "left", margin: 0
  });

  const takeaways = [
    { num: "01", text: "Global emissions exceed 35 Bt/yr and have not yet peaked, despite slowing growth." },
    { num: "02", text: "China is the largest annual emitter (~31%) but its per capita emissions (~9 t) remain below the US (~14 t)." },
    { num: "03", text: "Historical responsibility is dominated by Europe and the US, which accounted for >90% of emissions in 1900." },
    { num: "04", text: "Per capita gaps of 150× persist between the richest (US/Canada at ~14 t) and poorest nations (Chad/Niger at ~0.1 t)." },
    { num: "05", text: "Energy policy and technology choices can decouple prosperity from emissions — France and the UK prove this is possible." }
  ];

  takeaways.forEach((t, i) => {
    const ty = 1.6 + i * 0.72;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.6, y: ty, w: 0.5, h: 0.5, fill: { color: theme.accent }
    });
    slide.addText(t.num, {
      x: 0.6, y: ty, w: 0.5, h: 0.5,
      fontSize: 14, fontFace: "Georgia", color: theme.primary, bold: true, align: "center", valign: "middle", margin: 0
    });
    slide.addText(t.text, {
      x: 1.3, y: ty, w: 8.2, h: 0.55,
      fontSize: 13, fontFace: "Calibri", color: "DDDDDD", bold: false, align: "left", valign: "middle", margin: 0
    });
  });

  // Source
  slide.addText("Data: Global Carbon Budget 2025 via Our World in Data  |  ourworldindata.org/co2-emissions", {
    x: 0.6, y: 5.15, w: 7, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: "888888", bold: false, align: "left", margin: 0
  });

  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("9", { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  return slide;
}

module.exports = { createSlide, slideConfig };

